script:
(function () {
  'use strict';
  // Retirement plan, annual steps. Saving: balance = balance x (1 + pre-retirement return) + savePct x
  // income, income rising each year. Need at retirement: present value of withdrawals that start at
  // needPct x final income less other income, rise with inflation and are taken at the start of each
  // year, discounted at the retirement return (a growing annuity due). Checked in Node: with 0%
  // return and inflation, $50,000 a year for 20 years needs $1,000,000 and $500,000 lasts 10 years;
  // the needed amount matches the closed form PMT x (1 - (1.03/1.05)^25) / (1 - 1.03/1.05); savings
  // match S x 1.06^n + C x (1.06^n - 1.02^n) / 0.04; the extra yearly saving grows to exactly the gap.
  // Annual model. Working years: end-of-year saving of savePct x that year's income, balance
  // grows at preRate. Retirement: the first year's spending need is needPct x income at the
  // retirement date, less other income (entered in today's dollars, grown with inflation); the
  // net need rises with inflation and is withdrawn at the start of each year; the rest earns postRate.
  // p: age, retireAge, lifeExp, income, raise, needPct, savings, savePct, preRate, postRate,
  // inflation (decimals), other (today's $ per year).
  function plan(p) {
    var n = p.retireAge - p.age, R = p.lifeExp - p.retireAge;
    var bal = p.savings, income = p.income, rows = [], saved = 0;
    for (var y = 0; y < n; y++) {
      var c = income * p.savePct, growth = bal * p.preRate;
      bal = bal + growth + c; saved += c;
      rows.push({ age: p.age + y, flow: c, growth: growth, balance: bal });
      income = income * (1 + p.raise);
    }
    var atRetire = bal;
    var infAtRetire = Math.pow(1 + p.inflation, n);
    var spend0 = p.needPct * income;               // income has grown to the retirement date
    var other0 = p.other * infAtRetire;
    var net0 = Math.max(0, spend0 - other0);
    // Present value at retirement of R inflation-growing withdrawals made at the start of each year.
    var needed = 0;
    for (var j = 0; j < R; j++) needed += net0 * Math.pow(1 + p.inflation, j) / Math.pow(1 + p.postRate, j);
    // Run the retirement years (and beyond life expectancy, up to age 120, to see how long money lasts).
    var lastsYears = null, b = atRetire;
    for (var k = 0; p.retireAge + k < 120; k++) {
      var w = net0 * Math.pow(1 + p.inflation, k);
      if (w > b + 1e-9) {
        if (lastsYears === null) lastsYears = k + (w > 0 ? b / w : 0);
        if (k < R) rows.push({ age: p.retireAge + k, flow: -b, growth: 0, balance: 0, out: true });
        b = 0;
        if (k >= R) break;
        continue;
      }
      var g = (b - w) * p.postRate;
      b = b - w + g;
      if (k < R) rows.push({ age: p.retireAge + k, flow: -w, growth: g, balance: b, out: false });
    }
    var gap = needed - atRetire;
    var extraYear = 0;
    if (gap > 0 && n > 0) extraYear = p.preRate === 0 ? gap / n : gap * p.preRate / (Math.pow(1 + p.preRate, n) - 1);
    return {
      atRetire: atRetire, real: atRetire / infAtRetire, needed: needed, gap: gap, saved: saved,
      spend0: spend0, other0: other0, net0: net0, lastsYears: lastsYears, R: R, n: n, extraYear: extraYear, rows: rows
    };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); } };

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var age = Math.round(num('rpAge')), retireAge = Math.round(num('rpRetireAge')), lifeExp = Math.round(num('rpLifeExp')),
        income = num('rpIncome'), raise = num('rpRaise'), needPct = num('rpNeed'), savings = num('rpSavings'),
        savePct = num('rpSave'), preRate = num('rpPreRate'), postRate = num('rpPostRate'),
        inflation = num('rpInflation'), other = num('rpOther');
    var error = document.getElementById('rpError');
    var bad = [age, retireAge, lifeExp, income, raise, needPct, savings, savePct, preRate, postRate, inflation, other].some(isNaN) ||
              age < 16 || age > 99 || retireAge < age || retireAge > 100 || lifeExp <= retireAge || lifeExp > 120 ||
              income < 0 || savings < 0 || other < 0 || raise < 0 || raise > 20 || needPct < 0 || needPct > 300 ||
              savePct < 0 || savePct > 100 || preRate < 0 || preRate > 30 || postRate < 0 || postRate > 30 ||
              inflation < 0 || inflation > 20;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Check your ages (retirement age at or above current age, life expectancy above retirement age, ' +
                          'up to 120), use non-negative amounts, returns up to 30% and inflation up to 20%.';
      return;
    }
    var r = plan({ age: age, retireAge: retireAge, lifeExp: lifeExp, income: income, raise: raise / 100,
                   needPct: needPct / 100, savings: savings, savePct: savePct / 100, preRate: preRate / 100,
                   postRate: postRate / 100, inflation: inflation / 100, other: other });
    set('rpAtRetireLabel', 'Savings at age ' + retireAge);
    set('rpAtRetire', money.format(r.atRetire));
    set('rpReal', money.format(r.real));
    set('rpNeeded', money.format(r.needed));
    var gapLabel = document.getElementById('rpGapLabel');
    if (r.gap > 0.5) {
      gapLabel.textContent = 'Shortfall';
      set('rpGap', money.format(r.gap));
    } else {
      gapLabel.textContent = 'Surplus';
      set('rpGap', money.format(-r.gap));
    }
    set('rpSpend', 'First year of retirement: you need ' + money.format(r.spend0) + ', other income covers ' +
        money.format(Math.min(r.other0, r.spend0)) + ', so savings must supply ' + money.format(r.net0) +
        ' (rising with inflation each year).');
    var lasts;
    if (r.lastsYears === null) lasts = 'Your savings last beyond age 120 on these assumptions.';
    else lasts = 'Your savings run out at about age ' + Math.floor(retireAge + r.lastsYears) +
                 (r.lastsYears < r.R ? ', before your planned life expectancy of ' + lifeExp + '.' : ', after your planned life expectancy of ' + lifeExp + '.');
    set('rpLasts', lasts);
    var extraEl = document.getElementById('rpExtra');
    extraEl.hidden = !(r.gap > 0.5);
    if (r.gap > 0.5) {
      extraEl.textContent = r.n > 0
        ? 'To close the gap, save about ' + money.format(r.extraYear) + ' more per year (' +
          money.format(r.extraYear / 12) + ' a month) until you retire, or adjust your retirement age or spending.'
        : 'You are already at your retirement age, so the gap can only be closed by spending less, working longer or adding income.';
    }
    var body = document.getElementById('rpSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      var phase = row.age < retireAge ? 'Saving' : 'Retired';
      [row.age, phase, row.flow >= 0 ? money.format(row.flow) : money.format(-row.flow).replace('$', '-$'), money.format(row.growth), money.format(row.balance)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rpForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
